<?php
namespace App\Http\Requests\Faqs; use App\Models\FaqGroup; use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rule; class SaveFaqRequest extends FormRequest { public function authorize():bool{return $this->user()!==null;} protected function prepareForValidation():void{$this->merge(['is_featured'=>$this->boolean('is_featured')]);} public function rules():array{return ['faq_group_id'=>['nullable',Rule::exists(FaqGroup::class,'id')->where('is_active',true)],'question'=>['required','string','max:300'],'answer'=>['required','string','max:10000'],'is_featured'=>['boolean']];} }
